mapper.select:
SELECT , , , , o.status AS orderStatus, bu.nickname AS buyerName, st.store_name AS storeName, s.supplier_name AS supplierName, eu.nickname AS userName
so.is_deleted = 0
AND (so.outbound_no LIKE CONCAT('%', #{q.keyword}, '%') OR so.order_no LIKE CONCAT('%', #{q.keyword}, '%') OR so.remark LIKE CONCAT('%', #{q.keyword}, '%') OR bu.nickname LIKE CONCAT('%', #{q.keyword}, '%') OR eu.nickname LIKE CONCAT('%', #{q.keyword}, '%'))
AND so.order_id = #{q.orderId}
AND so.outbound_source = #{q.outboundSource}
AND so.status = #{q.status}
AND so.user_id = #{q.userId}
AND so.create_time >= #{q.beginTime}
AND so.create_time <= #{q.endTime}
ORDER BY so.id DESC
